import pygame
import math
import random

# Initialize pygame
pygame.init()
screen = pygame.display.set_mode((800, 600))
pygame.display.set_caption("VR Adult Content Simulator (2D Demo)")

# Colors
BLACK = (0, 0, 0)
WHITE = (255, 255, 255)
RED = (255, 0, 0)
BLUE = (0, 0, 255)

# User "avatar" (represented as a circle)
avatar_radius = 20
avatar_x, avatar_y = 400, 300
avatar_speed = 5

# Interactive objects (e.g., "buttons" to trigger scenes)
buttons = [
    {"rect": pygame.Rect(100, 100, 100, 50), "color": RED, "text": "Scene 1", "scene": "romantic"},
    {"rect": pygame.Rect(250, 100, 100, 50), "color": BLUE, "text": "Scene 2", "scene": "fantasy"},
    {"rect": pygame.Rect(400, 100, 100, 50), "color": GREEN, "text": "Customize", "scene": "avatar"}
]

# Current scene
current_scene = "neutral"

# Font for text
font = pygame.font.SysFont(None, 36)

def draw_avatar():
    pygame.draw.circle(screen, BLUE, (avatar_x, avatar_y), avatar_radius)

def draw_buttons():
    for button in buttons:
        pygame.draw.rect(screen, button["color"], button["rect"])
        text = font.render(button["text"], True, WHITE)
        screen.blit(text, (button["rect"].x + 10, button["rect"].y + 10))

def handle_click(pos):
    for button in buttons:
        if button["rect"].collidepoint(pos):
            return button["scene"]
    return None

def main():
    global avatar_x, avatar_y, current_scene

    clock = pygame.time.Clock()
    running = True

    while running:
        screen.fill(BLACK)

        # Event handling
        for event in pygame.event.get():
            if event.type == pygame.QUIT:
                running = False
            elif event.type == pygame.KEYDOWN:
                if event.key == pygame.K_LEFT:
                    avatar_x -= avatar_speed
                elif event.key == pygame.K_RIGHT:
                    avatar_x += avatar_speed
                elif event.key == pygame.K_UP:
                    avatar_y -= avatar_speed
                elif event.key == pygame.K_DOWN:
                    avatar_y += avatar_speed
            elif event.type == pygame.MOUSEBUTTONDOWN:
                if event.button == 1:  # Left click
                    scene = handle_click(event.pos)
                    if scene:
                        current_scene = scene
                        print(f"Triggered scene: {current_scene}")

        # Draw elements
        draw_avatar()
        draw_buttons()

        # Display scene info
        scene_text = font.render(f"Current Scene: {current_scene}", True, WHITE)
        screen.blit(scene_text, (50, 550))

        pygame.display.flip()
        clock.tick(60)

    pygame.quit()

if __name__ == "__main__":
    main()
```

