using UnityEngine;
using UnityEngine.XR.Interaction.Toolkit;

public class VRAdultSceneController : MonoBehaviour
{
    public GameObject[] scenes; // Array of different VR scenes
    public XRRayInteractor leftHandInteractor;
    public XRRayInteractor rightHandInteractor;

    private int currentSceneIndex = 0;

    void Start()
    {
        // Load the first scene
        LoadScene(currentSceneIndex);
    }

    void Update()
    {
        // Detect hand interactions (e.g., grabbing a "button")
        if (leftHandInteractor.selectTarget != null || rightHandInteractor.selectTarget != null)
